@verbatim
<template id="finance-overview-template">
<template v-if="['home','year','month'].includes(view.name)"><section class="stats-grid" aria-label="Підсумок бюджету"><article class="stat-card budget-stat"><div class="stat-label"><span class="stat-icon"><icon name="wallet"/></span><span>{{view.name==='home'?'Загальний бюджет':'Запланований бюджет'}}</span><span class="stat-period">{{view.name==='home'?'За всі роки':currentYear?.name}}</span></div><strong class="stat-amount">{{money(summary.budget)}}<small>грн</small></strong><div class="stat-foot"><span>Ваш план на {{view.name==='month'?'місяць':view.name==='year'?'рік':'всі періоди'}}</span><icon name="arrow"/></div></article><article class="stat-card"><div class="stat-label"><span class="stat-icon expense-icon"><icon name="down"/></span><span>Витрачено</span></div><strong class="stat-amount">{{money(summary.spent)}}<small>грн</small></strong><div class="stat-foot"><span>Фактичні витрати за період</span><span class="tiny-pill">{{summary.budget>0?Math.round(summary.spent/summary.budget*100):'—'}}{{summary.budget>0?'% бюджету':''}}</span></div></article><article class="stat-card"><div class="stat-label"><span class="stat-icon balance-icon"><icon name="arrow"/></span><span>{{remaining>=0?'Залишок бюджету':'Перевищення бюджету'}}</span></div><strong :class="['stat-amount',{negative:remaining<0}]">{{money(Math.abs(remaining))}}<small>грн</small></strong><div class="stat-foot"><span>{{remaining>=0?'Місце для ваших планів':'Витрати перевищують план'}}</span><span :class="['status-dot',{danger:remaining<0}]"></span></div></article></section></template>
            <template v-if="['home','year'].includes(view.name)"><nav v-if="view.name==='year'" class="chips year-chips" aria-label="Оберіть рік"><a v-for="year in state.years" :key="year.id" :href="url('/year/'+year.id)" :class="['chip',{selected:year.id===currentYear?.id}]" :aria-current="year.id===currentYear?.id?'page':null" @click.prevent="navigate('/year/'+year.id)">{{year.name}}</a></nav><div :class="['overview-columns',{'full-width':view.name==='year'}]"><section class="period-section"><div class="section-heading"><div><h2>{{view.name==='home'?'Бюджети за роками':'Бюджети за місяцями'}}</h2><p>{{view.name==='home'?'Від великих планів — до щоденних рішень':'Оберіть місяць, щоб перейти до витрат'}}</p></div><label v-if="view.name==='home'" class="sort-select"><span class="visually-hidden">Сортувати роки</span><custom-select v-model="sort" :options="[{label:'Спочатку нові',value:'desc'},{label:'Спочатку старі',value:'asc'}]" aria-label="Сортувати роки" variant="plain"/></label></div><label v-if="state.years.length" class="search-field"><icon name="search"/><input v-model="search" type="search" :placeholder="view.name==='home'?'Знайти рік…':'Знайти місяць…'" :aria-label="view.name==='home'?'Знайти рік':'Знайти місяць'"></label><div class="period-grid"><a v-for="period in periods" :key="period.id" :href="url((view.name==='home'?'/year/':'/month/')+period.id)" :class="['period-card',{'period-overdrawn':period.spent>period.budget}]" @click.prevent="navigate((view.name==='home'?'/year/':'/month/')+period.id)"><div class="period-card-top"><span class="surface-icon"><icon name="calendar"/></span><span :class="['badge',period.spent>period.budget?'warning':'blue']">{{period.spent>period.budget?'Перевищено':'У межах плану'}}</span></div><h3>{{period.name}}</h3><span class="label-small">Запланований бюджет</span><strong class="period-amount">{{money(period.budget)}} <small>грн</small></strong><div class="progress-caption"><span>Витрачено</span><strong>{{money(period.spent)}} грн</strong></div><div :class="['progress-track',{over:period.spent>period.budget}]" role="progressbar" :aria-label="'Використано бюджет: '+period.name" :aria-valuenow="Math.round(progress(period))" aria-valuemin="0" aria-valuemax="100"><span :style="{width:progress(period)+'%'}"></span></div><div class="period-bottom"><span>{{period.budget>=period.spent?'Залишок':'Перевищення'}} {{money(Math.abs(period.budget-period.spent))}} грн</span><span class="round-arrow"><icon name="right"/></span></div></a></div><div v-if="!periods.length" class="empty-state"><span class="empty-icon"><icon name="calendar"/></span><h3>{{search?'Нічого не знайдено':'Перший крок до ваших планів'}}</h3><p>{{search?'Спробуйте інший запит.':'Створіть рік, щоб почати планувати місячні бюджети.'}}</p><button v-if="search" class="button tonal" @click="search=''">Скинути пошук</button><button v-else class="button primary" @click="openDialog('year')"><icon name="plus"/>Створити рік</button></div></section><aside v-if="view.name==='home'" class="panel recent-panel"><div class="section-heading"><div><h2>Останні витрати</h2><p>Ваша фінансова історія</p></div><span class="counter">{{state.recent.length}}</span></div><article v-for="row in state.recent" :key="row.id" class="recent-row"><span class="recent-icon"><icon name="wallet"/></span><div class="recent-copy"><h3>{{row.title}}</h3><p>{{row.category||'Без категорії'}}</p><time>{{dateLabel(row.created_at)}}</time></div><strong>−{{money(row.amount)}}<small>грн</small></strong></article><div v-if="!state.recent.length" class="empty-state compact"><icon name="wallet"/><h3>Витрат поки немає</h3><p>Відкрийте бюджет місяця та додайте першу транзакцію.</p></div><a class="panel-link" :href="url('/transactions')" @click.prevent="navigate('/transactions')">Усі транзакції<icon name="right"/></a></aside></div></template>
</template>
@endverbatim
